@using System.Threading
@inject IProductService ProductService
@implements IDisposable

<div class="product-search">
    <input type="text"
           placeholder="Search products…"
           @oninput="OnSearchInput"
           value="@_query" />

    @if (_loading)
    {
        <div class="product-search-status">Searching…</div>
    }
    else if (_error is not null)
    {
        <div class="product-search-status product-search-error">
            Something went wrong. Please try again.
        </div>
    }
    else if (_searched && _results.Count == 0)
    {
        <div class="product-search-status">No products found.</div>
    }

    @if (_results.Count > 0)
    {
        <div class="product-search-results">
            @foreach (var product in _results)
            {
                <div class="product-card" @onclick="() => OnProductSelected.InvokeAsync(product)">
                    <img src="@product.ImageUrl" alt="@product.Name" />
                    <div class="product-card-info">
                        <span class="product-card-name">@product.Name</span>
                        <span class="product-card-price">@product.Price.ToString("C")</span>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private string _query = string.Empty;
    private bool _loading;
    private bool _searched;
    private Exception? _error;
    private List<Product> _results = new();

    private CancellationTokenSource? _debounceCts;
    private CancellationTokenSource? _searchCts;
    private Timer? _debounceTimer;

    private async Task OnSearchInput(ChangeEventArgs e)
    {
        _query = e.Value?.ToString() ?? string.Empty;

        // Cancel any pending debounce and in-flight search.
        _debounceCts?.Cancel();
        _debounceCts?.Dispose();
        _debounceCts = new CancellationTokenSource();
        var token = _debounceCts.Token;

        _debounceTimer?.Dispose();

        if (string.IsNullOrWhiteSpace(_query))
        {
            _loading = false;
            _error = null;
            _searched = false;
            _results = new();
            return;
        }

        // Debounce: wait 300ms before firing the search.
        _debounceTimer = new Timer(_ =>
        {
            _ = InvokeAsync(() => ExecuteSearchAsync(_query, token));
        }, null, 300, Timeout.Infinite);
    }

    private async Task ExecuteSearchAsync(string query, CancellationToken debounceToken)
    {
        if (debounceToken.IsCancellationRequested)
            return;

        // Cancel any previous in-flight search.
        _searchCts?.Cancel();
        _searchCts?.Dispose();
        _searchCts = new CancellationTokenSource();

        // Link debounce and search tokens so either can cancel the call.
        using var linked = CancellationTokenSource.CreateLinkedTokenSource(
            debounceToken, _searchCts.Token);

        _loading = true;
        _error = null;
        StateHasChanged();

        try
        {
            _results = await ProductService.SearchAsync(query, linked.Token);
            _searched = true;
            _error = null;
        }
        catch (OperationCanceledException)
        {
            // Search was superseded — discard silently.
            return;
        }
        catch (Exception ex)
        {
            _results = new();
            _error = ex;
        }
        finally
        {
            if (!linked.IsCancellationRequested)
            {
                _loading = false;
                StateHasChanged();
            }
        }
    }

    public void Dispose()
    {
        _debounceTimer?.Dispose();
        _debounceCts?.Cancel();
        _debounceCts?.Dispose();
        _searchCts?.Cancel();
        _searchCts?.Dispose();
    }
}

